with feeders as (
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__UTR_NO))) as HUB_FINANCIAL_TRANSACTION_HK
        , PAYABLE_TO_INVESTIGATOR as NET_PAID_AMOUNT
        , PAY_STATUS as PAYMENT_STATUS
        , CHEQUE_DATE as CHEQUE_DATE
        , CHEQUE_REC_DATE as CHEQUE_RECEIVED_DATE
        , CHEQUE_DIS_DATE as CHEQUE_DISPATCH_DATE
        , UTR_NO as UTR_NUMBER
        , TDS_AMOUNT as TDS_ON_CLAIM_AMOUNT
        , MODE_OF_PAYMENT as PAYMENT_MODE
        , cast(null as varchar) as PAYMENT_DATE
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(UTR_NO),'')) is not null
    union all
    select
        md5(upper('HUB_FINANCIAL_TRANSACTION|' || (HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY))) as HUB_FINANCIAL_TRANSACTION_HK
        , NET_PAYBLE_AMT as NET_PAID_AMOUNT
        , cast(null as varchar) as PAYMENT_STATUS
        , CHEQUE_DATE as CHEQUE_DATE
        , cast(null as varchar) as CHEQUE_RECEIVED_DATE
        , cast(null as varchar) as CHEQUE_DISPATCH_DATE
        , cast(null as varchar) as UTR_NUMBER
        , TDS_AMOUNT as TDS_ON_CLAIM_AMOUNT
        , cast(null as varchar) as PAYMENT_MODE
        , PAYMENT_DATE as PAYMENT_DATE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(TPA_TRANS_KEY),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_TRANSACTION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NET_PAID_AMOUNT end) as NET_PAID_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAYMENT_STATUS end) as PAYMENT_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHEQUE_DATE end) as CHEQUE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHEQUE_RECEIVED_DATE end) as CHEQUE_RECEIVED_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHEQUE_DISPATCH_DATE end) as CHEQUE_DISPATCH_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then UTR_NUMBER end) as UTR_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TDS_ON_CLAIM_AMOUNT end) as TDS_ON_CLAIM_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAYMENT_MODE end) as PAYMENT_MODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAYMENT_DATE end) as PAYMENT_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_TRANSACTION_HK
),

hashed as (
    select
        *,
        case when NET_PAID_AMOUNT is not null or PAYMENT_STATUS is not null or CHEQUE_DATE is not null or CHEQUE_RECEIVED_DATE is not null or CHEQUE_DISPATCH_DATE is not null or UTR_NUMBER is not null or TDS_ON_CLAIM_AMOUNT is not null or PAYMENT_MODE is not null or PAYMENT_DATE is not null
                     then md5(upper(coalesce(cast(NET_PAID_AMOUNT as varchar), '') || '|' || coalesce(cast(PAYMENT_STATUS as varchar), '') || '|' || coalesce(cast(CHEQUE_DATE as varchar), '') || '|' || coalesce(cast(CHEQUE_RECEIVED_DATE as varchar), '') || '|' || coalesce(cast(CHEQUE_DISPATCH_DATE as varchar), '') || '|' || coalesce(cast(UTR_NUMBER as varchar), '') || '|' || coalesce(cast(TDS_ON_CLAIM_AMOUNT as varchar), '') || '|' || coalesce(cast(PAYMENT_MODE as varchar), '') || '|' || coalesce(cast(PAYMENT_DATE as varchar), '')))
                end as SAT_FINTXN_CLAIM_PAYMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_TRANSACTION_HK is not null
  and SAT_FINTXN_CLAIM_PAYMENT_HASHDIFF is not null
